describe('Password Strength Indicator', () => {
  beforeEach(() => {
    cy.visit('/password-reset');
  });

  it('should display password strength indicator and update as user types', () => {
    // Intercept the password reset API call
    cy.intercept('POST', '/api/password-reset').as('passwordReset');

    // Verify the password strength indicator is visible
    cy.get('[data-testid="password-strength-indicator"]').should('be.visible');

    // Verify initial strength is weak
    cy.get('[data-testid="password-strength-indicator"]').should('contain', 'Weak');

    // Type a weak password
    cy.get('[data-testid="new-password-input"]').type('password123');
    cy.get('[data-testid="password-strength-indicator"]').should('contain', 'Weak');

    // Type a medium password
    cy.get('[data-testid="new-password-input"]').type('Passw0rd123');
    cy.get('[data-testid="password-strength-indicator"]').should('contain', 'Medium');

    // Type a strong password
    cy.get('[data-testid="new-password-input"]').type('P@ssw0rd!2345');
    cy.get('[data-testid="password-strength-indicator"]').should('contain', 'Strong');

    // Verify the password strength indicator updates in real-time
    cy.get('[data-testid="new-password-input"]').type('P@ssw0rd!23456789');
    cy.get('[data-testid="password-strength-indicator"]').should('contain', 'Strong');

    // Verify the password reset form is still valid
    cy.get('[data-testid="password-reset-form"]').should('be.visible');
    cy.get('[data-testid="password-reset-form"]').should('have.class', 'valid');

    // Verify the password reset button is enabled
    cy.get('[data-testid="password-reset-button"]').should('be.visible');
    cy.get('[data-testid="password-reset-button"]').should('not.be.disabled');

    // Verify the password reset API call was made
    cy.wait('@passwordReset').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
  });

  it('should display error message when password does not meet strength requirements', () => {
    // Intercept the password reset API call
    cy.intercept('POST', '/api/password-reset').as('passwordReset');

    // Type a password that does not meet strength requirements
    cy.get('[data-testid="new-password-input"]').type('12345678');

    // Verify the password strength indicator shows weak
    cy.get('[data-testid="password-strength-indicator"]').should('contain', 'Weak');

    // Verify the password reset form is still visible
    cy.get('[data-testid="password-reset-form"]').should('be.visible');

    // Verify the password reset button is disabled
    cy.get('[data-testid="password-reset-button"]').should('be.disabled');

    // Verify the error message is displayed
    cy.get('[data-testid="password-strength-error"]').should('be.visible');
    cy.get('[data-testid="password-strength-error"]').should('contain', 'Password must be at least 8 characters long');

    // Verify the password reset API call was not made
    cy.wait('@passwordReset').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
    });
  });
});
